descriptor.templateCss:
.tg-map-card{
  height:100%;box-sizing:border-box;border-radius:14px;background:#fff;border:1px solid #dbe4ea;
  overflow:hidden;display:flex;flex-direction:column;font-family:"OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;color:#111827;
  box-shadow:0 1px 3px rgba(15,23,42,.05)
}
.tg-map-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;border-bottom:1px solid #d9f3ef;background:linear-gradient(180deg,#f0fdfa,#ecfeff)}
.tg-map-title{font-size:17px;line-height:1.25;font-weight:650;letter-spacing:-.01em;color:#0f4c5c}
.tg-map-sub{margin-top:3px;font-size:11.5px;color:#0f766e}
.tg-open-map{border:1px solid #99f6e4;border-radius:9px;padding:8px 11px;background:#fff;color:#0f766e;font:600 11.5px "OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;cursor:pointer;white-space:nowrap}
.tg-open-map:hover{background:#f0fdfa}
.tg-open-map:disabled{cursor:not-allowed;opacity:.45}
.tg-map-info{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;padding:8px 14px;background:#fbfefe;border-bottom:1px solid #e6f3f1}
.tg-map-info span{min-width:0;padding-right:12px}
.tg-map-info small{display:block;font-size:10.5px;color:#64748b;margin-bottom:2px}
.tg-map-info b{display:block;font-size:12.5px;font-weight:600;color:#0f172a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tg-map-info b.stale{color:#b45309}.tg-map-info b.fresh{color:#047857}
.tg-map-body{position:relative;flex:1;min-height:260px;background:#edf4f3}
.tg-map-frame{position:absolute;inset:0;width:100%;height:100%;border:0;background:#edf4f3}
.tg-map-empty{position:absolute;inset:0;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:linear-gradient(180deg,#f8fffe,#eef8f6);color:#334155;padding:20px}
.tg-map-empty-title{font-size:15px;font-weight:650;color:#0f4c5c}
.tg-map-empty-sub{margin-top:5px;font-size:11.5px;color:#64748b;max-width:360px}
@media(max-width:700px){
  .tg-map-head{align-items:flex-start;padding:11px 12px}
  .tg-map-title{font-size:15px}
  .tg-open-map{padding:7px 9px;font-size:11px}
  .tg-map-info{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:7px;padding:8px 12px}
  .tg-map-body{min-height:300px}
}

descriptor.controllerScript:
var tgMapFrame;
var tgLastFrameKey = '';
var tgLastFrameUpdate = 0;

function tgLatestValue(name) {
  var rows = self.ctx.data || [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row.dataKey || row.dataKey.name !== name || !row.data || !row.data.length) {
      continue;
    }
    var newest = row.data[0];
    for (var j = 1; j < row.data.length; j++) {
      if (row.data[j][0] > newest[0]) { newest = row.data[j]; }
    }
    return newest[1];
  }
  return null;
}

function tgAsBoolean(value) {
  return value === true || value === 1 || value === '1' || value === 'true';
}

function tgRenderMap(force) {
  var scope = self.ctx.$scope;
  var latitude = Number(tgLatestValue('latitude'));
  var longitude = Number(tgLatestValue('longitude'));
  var speed = Number(tgLatestValue('speed_kmh'));
  var satellites = Number(tgLatestValue('satellites'));
  var gpsState = tgLatestValue('gps_state');
  var current = tgAsBoolean(tgLatestValue('position_current'));
  var valid = Number.isFinite(latitude) && Number.isFinite(longitude) &&
      latitude >= -90 && latitude <= 90 && longitude >= -180 && longitude <= 180 &&
      !(latitude === 0 && longitude === 0);

  scope.hasPosition = valid;
  scope.latitudeText = valid ? latitude.toFixed(7) : '--';
  scope.longitudeText = valid ? longitude.toFixed(7) : '--';
  scope.speedText = Number.isFinite(speed) ? speed.toFixed(1) + ' km/h' : '--';
  scope.satellitesText = Number.isFinite(satellites) ? String(Math.round(satellites)) : '--';
  scope.positionText = valid ? (current ? 'MỚI' : 'CŨ') : 'CHƯA CÓ';
  scope.positionClass = valid && current ? 'fresh' : 'stale';
  scope.status = valid ? ('GPS ' + (gpsState || 'đã có tọa độ')) : ('GPS ' + (gpsState || 'đang chờ fix'));

  if (valid && tgMapFrame) {
    var refreshMs = Math.max(2000, Number(self.ctx.settings.mapRefreshMs || 5000));
    var delta = Math.max(0.001, Number(self.ctx.settings.mapSpanDegrees || 0.01));
    var frameKey = latitude.toFixed(5) + ',' + longitude.toFixed(5);
    var now = Date.now();
    if (force || (frameKey !== tgLastFrameKey && now - tgLastFrameUpdate >= refreshMs)) {
      var bbox = [longitude - delta, latitude - delta, longitude + delta, latitude + delta]
        .map(function(v) { return v.toFixed(7); }).join('%2C');
      tgMapFrame.src = 'https://www.openstreetmap.org/export/embed.html?bbox=' + bbox +
        '&layer=mapnik&marker=' + latitude.toFixed(7) + '%2C' + longitude.toFixed(7);
      tgMapFrame.style.display = 'block';
      tgLastFrameKey = frameKey;
      tgLastFrameUpdate = now;
    }
  } else if (tgMapFrame) {
    tgMapFrame.style.display = 'none';
  }

  scope.openExternalMap = function() {
    if (!scope.hasPosition) { return; }
    window.open('https://www.openstreetmap.org/?mlat=' + latitude.toFixed(7) +
      '&mlon=' + longitude.toFixed(7) + '#map=17/' + latitude.toFixed(7) + '/' +
      longitude.toFixed(7), '_blank', 'noopener,noreferrer');
  };
  if (scope.$evalAsync) { scope.$evalAsync(); }
}

self.onInit = function() {
  var root = self.ctx.$container && self.ctx.$container[0];
  tgMapFrame = root ? root.querySelector('.tg-map-frame') : null;
  tgRenderMap(true);
};

self.onDataUpdated = function() {
  tgRenderMap(false);
};

self.typeParameters = function() {
  return {
    maxDatasources: 1,
    dataKeysOptional: false,
    singleEntity: true,
    previewWidth: '900px',
    previewHeight: '480px'
  };
};

self.onDestroy = function() {
  if (tgMapFrame) { tgMapFrame.src = 'about:blank'; }
};
